def calculer_score(reponses, items, inverses):
    total = 0
    for cle in items:
        val = reponses[cle]
        if cle in inverses:
            val = 6 - val
        total += val
    return total / len(items)

participants = [
    {'id': 'P1', 'Q1': 4, 'Q2': 2, 'Q3': 5, 'Q4': 3},
    {'id': 'P2', 'Q1': 2, 'Q2': 4, 'Q3': 1, 'Q4': 5}
]
echelles = {
    'Anxiete': {'items': ['Q1', 'Q3'], 'inverses': ['Q3']},
    'Extraversion': {'items': ['Q2', 'Q4'], 'inverses': []}
}

resultats = {}
for p in participants:
    scores = {}
    for nom, cfg in echelles.items():
        s = calculer_score(p, cfg['items'], cfg['inverses'])
        scores[nom] = s
    resultats[p['id']] = scores

print(resultats)
